<?php
namespace Alprof\Services;
use PDO; use Throwable;
final class GroupDashboardService{
 public function __construct(private PDO $db){}
 private function v(string $sql,array $p=[]):float{try{$q=$this->db->prepare($sql);$q->execute($p);return(float)($q->fetchColumn()?:0);}catch(Throwable){return 0;}}
 private function r(string $sql,array $p=[]):array{try{$q=$this->db->prepare($sql);$q->execute($p);return$q->fetchAll()?:[];}catch(Throwable){return[];}}
 public function groups():array{return$this->r('SELECT g.id,g.name,g.color,gl.name grade_name FROM groups g JOIN grade_levels gl ON gl.id=g.grade_level_id ORDER BY gl.sort_order,g.name');}
 public function summary(int $g):array{$m=date('Y-m-01');$n=date('Y-m-01',strtotime('+1 month'));$l=date('Y-m-01',strtotime('-1 month'));$active=(int)$this->v("SELECT COUNT(*) FROM students WHERE group_id=? AND status='active'",[$g]);$present=(int)$this->v("SELECT COUNT(*) FROM attendance a JOIN students s ON s.id=a.student_id WHERE s.group_id=? AND s.status='active' AND a.attendance_date=CURDATE() AND a.status='present'",[$g]);$exam=$this->r('SELECT id,max_score FROM exams WHERE group_id=? ORDER BY exam_date DESC,id DESC LIMIT 1',[$g]);$avg=0;if($exam){$raw=$this->v('SELECT AVG(score) FROM exam_scores WHERE exam_id=?',[$exam[0]['id']]);$avg=(float)$exam[0]['max_score']>0?round($raw/(float)$exam[0]['max_score']*100,1):0;}return['month_revenue'=>$this->v("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN students s ON s.id=p.student_id WHERE s.group_id=? AND p.reversed_at IS NULL AND p.paid_at>=? AND p.paid_at<?",[$g,$m,$n]),'total_revenue'=>$this->v("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN students s ON s.id=p.student_id WHERE s.group_id=? AND p.reversed_at IS NULL",[$g]),'overdue'=>$this->v("SELECT COALESCE(SUM(GREATEST(0,mf.assessed_amount+mf.previous_arrears-mf.paid_amount)),0) FROM monthly_fees mf JOIN students s ON s.id=mf.student_id WHERE s.group_id=? AND mf.fee_month=?",[$g,$l]),'unpaid'=>(int)$this->v("SELECT COUNT(DISTINCT mf.student_id) FROM monthly_fees mf JOIN students s ON s.id=mf.student_id WHERE s.group_id=? AND s.status='active' AND mf.fee_month=? AND mf.status IN('unpaid','partial')",[$g,$m]),'active'=>$active,'attendance_rate'=>$active?round($present/$active*100,1):0,'archived'=>(int)$this->v("SELECT COUNT(*) FROM students WHERE group_id=? AND status='archived'",[$g]),'exam_average'=>$avg,'missing_phone'=>(int)$this->v("SELECT COUNT(*) FROM students s WHERE s.group_id=? AND s.status='active' AND NOT EXISTS(SELECT 1 FROM student_phones p WHERE p.student_id=s.id)",[$g]),'missing_fee'=>(int)$this->v("SELECT COUNT(*) FROM students s JOIN groups gr ON gr.id=s.group_id WHERE s.group_id=? AND s.status='active' AND s.monthly_fee_override IS NULL AND gr.monthly_fee<=0",[$g])];}
 public function alerts(int $g):array{$s=date('Y-m-01');$n=date('Y-m-01',strtotime('+1 month'));return['homework'=>$this->r("SELECT st.name,COUNT(*) occurrences FROM homework_results x JOIN students st ON st.id=x.student_id WHERE st.group_id=? AND st.status='active' AND x.status='incomplete' AND x.assigned_date>=? AND x.assigned_date<? GROUP BY st.id,st.name HAVING COUNT(*)>=3 ORDER BY occurrences DESC LIMIT 10",[$g,$s,$n]),'absence'=>$this->r("SELECT st.name,COUNT(*) occurrences FROM attendance x JOIN students st ON st.id=x.student_id WHERE st.group_id=? AND st.status='active' AND x.status='absent' AND x.attendance_date>=? AND x.attendance_date<? GROUP BY st.id,st.name HAVING COUNT(*)>=3 ORDER BY occurrences DESC LIMIT 10",[$g,$s,$n]),'exams'=>$this->r("SELECT st.name,COUNT(*) occurrences FROM exam_scores x JOIN exams e ON e.id=x.exam_id JOIN students st ON st.id=x.student_id WHERE st.group_id=? AND st.status='active' AND e.max_score>0 AND x.score/e.max_score<0.5 GROUP BY st.id,st.name HAVING COUNT(*)>=3 ORDER BY occurrences DESC LIMIT 10",[$g]),'recitation'=>$this->r("SELECT st.name,COUNT(*) occurrences FROM recitation_results x JOIN students st ON st.id=x.student_id WHERE st.group_id=? AND st.status='active' AND x.errors_count>0 AND x.recitation_date>=? AND x.recitation_date<? GROUP BY st.id,st.name HAVING COUNT(*)>=3 ORDER BY occurrences DESC LIMIT 10",[$g,$s,$n])];}
 public function top(int $g):array{return$this->r("SELECT st.name,ROUND(AVG(x.score/e.max_score*100),1) average_score,COUNT(*) exam_count FROM exam_scores x JOIN exams e ON e.id=x.exam_id JOIN students st ON st.id=x.student_id WHERE st.group_id=? AND st.status='active' AND e.max_score>0 GROUP BY st.id,st.name ORDER BY average_score DESC LIMIT 10",[$g]);}
 public function archive(int $g):array{return$this->r("SELECT s.id,s.name,s.joined_at,s.monthly_fee_override,s.archived_at,s.archive_reason,u.name archived_by_name FROM students s LEFT JOIN users u ON u.id=s.archived_by WHERE s.group_id=? AND s.status='archived' ORDER BY s.archived_at DESC",[$g]);}
}
